import type { ReactNode } from "react";
import iconMap from "../techIcons.json";
import scrapedMap from "../techIconsScraped.json";

/**
 * Local logos for detected technologies (frameworks, languages, apps, services).
 * `public/tech-icons/<id>.svg` is generated by `scripts/vendor-tech-icons.py` from CC0 icon sets, so the
 * sidebar never depends on a logo service or network. Technologies with no brand mark get a category
 * glyph; a letter tile is the last resort.
 */
const MAP = iconMap as Record<string, { tone: "light" | "dark" }>;
/** Marks fetched from each tool's own site by `scripts/scrape-tech-icons.py` (svg / png / ico). */
const SCRAPED = scrapedMap as Record<string, { ext: string; tone: "light" | "dark" }>;

/** "googletagmanager" -> "google-tag-manager": names and hosts drop the hyphens that ids keep. */
const NORMALISED: Record<string, string> = (() => {
  const out: Record<string, string> = {};
  for (const key of [...Object.keys(MAP), ...Object.keys(SCRAPED)]) out[key.replace(/[^a-z0-9]/g, "")] = key;
  return out;
})();

function lookup(k0: string): TechIcon | null {
  const k = MAP[k0] || SCRAPED[k0] ? k0 : NORMALISED[k0] ?? k0;
  if (MAP[k]) return { src: `/tech-icons/${k}.svg`, tone: MAP[k].tone };
  if (SCRAPED[k]) return { src: `/tech-icons/scraped/${k}.${SCRAPED[k].ext}`, tone: SCRAPED[k].tone };
  return null;
}

function norm(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]/g, "");
}

/** Extra spellings of names the scanner and the app scan use. */
const ALIASES: Record<string, string> = {
  js: "javascript",
  ts: "typescript",
  golang: "go",
  csharp: "dotnet",
  nodejs: "nodejs",
  node: "nodejs",
  next: "nextjs",
  nuxt: "nuxtjs",
  visualstudiocode: "vscode",
  googlechrome: "chrome",
  microsoftedge: "edge",
  vlcmediaplayer: "vlc",
  windowsterminal: "terminal",
  fileexplorer: "fileexplorer",
  powershell7: "powershell",
  cplusplus: "cpp",
  csharpnet: "csharp",
};

export interface TechIcon {
  src: string;
  tone: "light" | "dark";
}

/** The bundled logo for a detection id or product name, or null. Pure. */
export function techIconFor(id?: string | null, name?: string | null): TechIcon | null {
  const tries = [id ?? "", name ?? "", norm(name ?? ""), ALIASES[norm(name ?? "")] ?? "", ALIASES[norm(id ?? "")] ?? ""];
  for (const t of tries) {
    if (!t) continue;
    for (const k of [t, t.toLowerCase(), norm(t)]) {
      const hit = lookup(k);
      if (hit) return hit;
    }
    // names like "Next.js 15" or "React 19": drop the trailing version
    const bare = norm(t.replace(/\s*v?[\d.]+$/, ""));
    for (const k of [bare, ALIASES[bare] ?? ""]) {
      const hit = k ? lookup(k) : null;
      if (hit) return hit;
    }
  }
  return null;
}

/** A bundled logo for a host name ("www.googletagmanager.com" -> Google Tag Manager), or null. */
export function techIconForHost(host?: string | null): TechIcon | null {
  if (!host) return null;
  const labels = host.toLowerCase().replace(/^www\./, "").split(".").filter(Boolean);
  // registrable-ish name first ("googletagmanager"), then any other label ("fonts.googleapis.com" -> googleapis)
  const order = [...labels.slice(0, -1).reverse(), labels.slice(0, -1).join("")];
  for (const l of order) {
    const hit = l ? techIconFor(null, l) : null;
    if (hit) return hit;
  }
  return null;
}

