/** Headers, protocols and browser hints have no brand: each gets a glyph that says what it is. */
const ID_GLYPH: Record<string, keyof typeof GLYPHS> = {
  hsts: "lock",
  "expect-ct": "lock",
  gzip: "box",
  http3: "bolt",
  "early-hints": "bolt",
  preload: "bolt",
  prefetch: "bolt",
  preconnect: "bolt",
  "dns-prefetch": "bolt",
  modulepreload: "bolt",
  "service-worker": "gear",
};

/** A small outline glyph for a category, on a calm tinted tile. Null when the category is unknown. */
export function categoryGlyph(category?: string | null, id?: string | null): { svg: ReactNode; hue: number; label: string } | null {
  const key = (id ? ID_GLYPH[id] : undefined) ?? (category ? CATEGORY_GLYPH[category.toLowerCase().replace(/_/g, "-")] : undefined);
  if (!key) return null;
  const g = GLYPHS[key];
  return { svg: <svg viewBox="0 0 24 24" aria-hidden="true">{g.path}</svg>, hue: g.hue, label: g.label };
}
